Can one instead find a sequence of smooth projective geometrically
connected curves $C_n/\mathbb Q$ with $g(C_n)\to\infty$ and
\begin{equation}\label{eq:intro-statement-1}
 \log\mathfrak N(C_n)=O(g(C_n))?
\end{equation}

\label{thm:main-surface}
There exist a regular projective arithmetic surface $S$ over $\operatorname{Spec}\mathbb Z$,
a section $s:\operatorname{Spec}\mathbb Z\to S$, and a tower
\begin{equation}\label{eq:intro-statement-4}
\cdots\longrightarrow S_{n+1}\longrightarrow S_n\longrightarrow\cdots
\longrightarrow S_0=S
\end{equation}
with the following properties.
\begin{enumerate}[label=(\roman*)]
\item Each $S_n\to S$ is a connected finite \'etale Galois cover of
degree $2^n$, and each transition map $S_{n+1}\to S_n$ has degree two.
\item Every $S_n$ is a regular projective arithmetic surface with
smooth geometrically connected generic fibre.
\item The section $s$ splits completely at every level:
\begin{equation}\label{eq:intro-statement-5}
S_n\times_{S,s}\operatorname{Spec}\mathbb Z\simeq\coprod_{j=1}^{2^n}\operatorname{Spec}\mathbb Z.
\end{equation}
\end{enumerate}
In particular, $\pi_1^{\mathrm{geom}}(S)=\pi_1^{\mathrm{\acute et}}(S)$ is infinite.

\label{thm:main-curves}
For every sufficiently large integer $g$, there are a smooth projective
geometrically connected curve $C/\mathbb Q$ of genus $g$, a point $P\in C(\mathbb Q)$,
and a tower of smooth projective geometrically connected curves
\begin{equation}\label{eq:intro-statement-6}
 \cdots\longrightarrow D_{n+1}\longrightarrow D_n
 \longrightarrow\cdots\longrightarrow D_0=C
\end{equation}
such that $D_n\to C$ is finite \'etale Galois of degree $2^n$ and $P$
splits completely in every $D_n$. In particular,
\begin{equation}\label{eq:intro-statement-7}
 g(D_n)-1=2^n(g-1),\qquad \#D_n(\mathbb Q)\ge2^n,
\end{equation}
and the $\mathbb Q$-rational geometric fundamental group of $(C,P)$ is infinite.

\label{thm:main-conductor}
There exist a constant $A>0$ and a sequence of smooth projective
geometrically connected curves $C_n/\mathbb Q$ such that
\begin{equation}\label{eq:intro-statement-10}
 g(C_n)\longrightarrow\infty,\qquad
 \log\mathfrak N(C_n)\le A g(C_n)\quad(n\ge0).
\end{equation}
The curves can be chosen in a tower with finite \'etale Galois maps
$C_n\to C_0$ of degree $2^n$, in which a point of $C_0(\mathbb Q)$ splits
completely at every level.

\label{prop:conductor-local-bound}
Let $D/F$ be a smooth projective geometrically connected curve over a
finite extension of $\mathbb Q_p$. Suppose $D$ acquires semistable reduction
over a finite Galois extension $E/F$. Put
\begin{equation}\label{eq:bg-explicit-last-break}
 b(E/F)=\sup\bigl(\{0\}\cup
       \{u>0:\operatorname{Gal}(E/F)^u\ne1\}\bigr).
\end{equation}
Then the integer $a_F(D)$ defined in
\eqref{eq:conductor-artin-swan} satisfies
\begin{equation}\label{eq:bg-explicit-local-bound}
 a_F(D)\le 2\bigl(1+b(E/F)\bigr)g(D).
\end{equation}

\label{prop:start-genera}
The curves $C_{-1}$ and $C_0$ satisfy
\begin{equation}\label{eq:start-explicit-genera}
 g(C_{-1})=g,\qquad g(C_0)=1+2^g(g-1).
\end{equation}

\label{prop:start-infinity}
Write $P_1=P_+$ and $P_{-1}=P_-$. For $\delta\in\{1,-1\}$, define
\begin{equation}\label{eq:start-infinity-sign-index-set}
 E_\delta=\left\{\boldsymbol\epsilon\in\{1,-1\}^{g+1}:
                                  \prod_{i=0}^g\epsilon_i=\delta\right\}.
\end{equation}
For $\boldsymbol\epsilon\in E_\delta$, let
$Q_{\boldsymbol\epsilon}\in U_{0,t}(\mathbb Q)$ be the point defined by
\begin{equation}\label{eq:start-explicit-infinity-points}
 t(Q_{\boldsymbol\epsilon})=0,\qquad
 v_i(Q_{\boldsymbol\epsilon})=\epsilon_i\quad(0\le i\le g).
\end{equation}
Then
\begin{equation}\label{eq:start-infinity-split-fibre}
 C_0\times_{C_{-1},P_\delta}\operatorname{Spec}\mathbb Q
       =\coprod_{\boldsymbol\epsilon\in E_\delta}
                                      \{Q_{\boldsymbol\epsilon}\}
       \simeq\coprod_{a=1}^{2^g}\operatorname{Spec}\mathbb Q.
\end{equation}
The action of $G_0$ on
$\{Q_{\boldsymbol\epsilon}:\boldsymbol\epsilon\in E_\delta\}$
is simply transitive.

\label{prop:start-integral-galois}
The morphism $\Pi_0:S_0\to S_{-1}$ is finite and surjective of
degree $2^g$. The extension of function fields induced by $\Pi_0$
is the Galois extension $L/K$, with group $G_0\simeq\mathbb F_2^g$, and
\begin{equation}\label{eq:start-model-automorphism-group}
 \operatorname{Aut}_{S_{-1}}(S_0)=\operatorname{Gal}(L/K)=G_0.
\end{equation}
The generic fibre of $\Pi_0$ is $\pi_0:C_0\to C_{-1}$.

\label{prop:start-integral-section}
The point $Q_+\in C_0(\mathbb Q)$ extends uniquely to a section
\begin{equation}\label{eq:fibres-explicit-section}
 s_0:\operatorname{Spec}\mathbb Z\longrightarrow S_0.
\end{equation}
The composite $s_{-1}=\Pi_0\circ s_0:\operatorname{Spec}\mathbb Z\to S_{-1}$
is the unique section extending $P_+\in C_{-1}(\mathbb Q)$.
The morphism $S_0\to\operatorname{Spec}\mathbb Z$ is smooth at every point
of $s_0(\operatorname{Spec}\mathbb Z)$, and
$S_{-1}\to\operatorname{Spec}\mathbb Z$ is smooth at every point of
$s_{-1}(\operatorname{Spec}\mathbb Z)$.
Moreover,
\begin{equation}\label{eq:fibres-explicit-split-section-fibre}
 S_0\times_{S_{-1},s_{-1}}\operatorname{Spec}\mathbb Z
 \simeq\coprod_{j=1}^{2^g}\operatorname{Spec}\mathbb Z.
\end{equation}

\label{prop:good-detection}
Let $\Sigma$ be a finite set of rational primes containing two, and put
\begin{equation}\label{eq:obs-explicit-detection-bases}
 U=\operatorname{Spec}\mathbb Z[1/\prod_{p\in\Sigma}p],
 \qquad K_p=\operatorname{Frac}(\mathbb Z_{(p)}^h).
\end{equation}
Let $f:X\to U$ be a smooth proper curve with geometrically connected
fibres and a section $s:U\to X$.  Suppose that
$R^1f_*\mathbb F_2$ is constant.  Write $C=X_{\mathbb Q}$.
Then restriction is injective:
\begin{equation}\label{eq:obs-explicit-detection-restriction}
 H^2_{\mathrm{\acute et}}(X,\mathbb F_2)
 \longrightarrow
 \bigoplus_{p\in\Sigma}
 H^2_{\mathrm{\acute et}}(C_{K_p},\mathbb F_2).
\end{equation}
The same assertion holds with $K_p$ replaced by $\mathbb Q_p$.

\label{prop:geometric-twist-obstruction}
For an anchored diagram, put
\begin{equation}\label{eq:obs-explicit-rational-integral-kernels}
 \mathscr R=\ker\bigl((\rho_p\alpha_p)_p\bigr),\qquad
 \mathscr L=\ker\bigl((\alpha_p)_p\bigr)
 \quad\text{inside }H^2(G,\mathbb F_2).
\end{equation}
Then $\mathscr R$ is the space of extension classes admitting a central
lift $P_{\mathbb Q}\to\widetilde C$, and $\mathscr L$ is the space
admitting a central lift $P_p\to\widetilde S_{B_p}$ for every
$p\in\Sigma$.
There is a canonical linear map
\begin{equation}\label{eq:obs-explicit-compatibility-map}
 \delta:\mathscr L\longrightarrow\mathcal D_\Sigma,
 \qquad \ker\delta=\mathscr E(\widetilde S,S_{-1}).
\end{equation}
In particular
\begin{equation}\label{eq:obs-explicit-obstruction-filtration}
 H^2(G,\mathbb F_2)\supseteq\mathscr R\supseteq\mathscr L
       \supseteq\mathscr E(\widetilde S,S_{-1}),
\end{equation}
and the successive quotients inject, respectively, into
\begin{equation}\label{eq:obs-explicit-quotient-targets}
 \bigoplus_{p\in\Sigma}\operatorname{im}\rho_p,
 \qquad\bigoplus_{p\in\Sigma}\ker\rho_p,
 \qquad\mathcal D_\Sigma.
\end{equation}
Consequently
\begin{equation}\label{eq:bad-only-obstruction-budget}
 \dim_{\mathbb F_2}\mathcal O(\widetilde S,S_{-1})
 \le\sum_{p\in\Sigma}\dim_{\mathbb F_2}\mathcal B_p^2
       +\dim_{\mathbb F_2}\mathcal D_\Sigma.
\end{equation}
The groups $\mathcal B_p^2$ and $\mathcal D_\Sigma$ depend only
on $q:S_0\to S_{-1}$ and $\Sigma$, independently of
$r:\widetilde S\to S_0$.

\label{prop:realizable-local-bounds}
For an anchored diagram, with $t=|\Sigma|-1$, one has for every
$p\in\Sigma$
\begin{equation}\label{eq:obs-explicit-local-dimension-bounds}
 \dim_{\mathbb F_2}\mathcal B_p^2\le
 \begin{cases}
 324g+324,&p\ne2,\\[2pt]
 (3g+1)/2,&p=2,
 \end{cases}
 \qquad
 \dim_{\mathbb F_2}\mathcal D_\Sigma\le(2g+2)t+(2g+3).
\end{equation}

\label{prop:uniform-realizable-obstruction}
Let $\widetilde S\to S_0\to S_{-1}$ be an anchored diagram, let
$g=g((S_{-1})_{\mathbb Q})$, and let $t=|\Sigma|-1$.  Then
\begin{equation}\label{eq:obs-explicit-uniform-obstruction-bound}
 \dim_{\mathbb F_2}\mathcal O(\widetilde S,S_{-1})
 \le(326g+326)t+\frac{7g+7}{2}
 \le\frac{5000g^2}{\log g}.
\end{equation}
In particular the implicit constant in
$\dim_{\mathbb F_2}\mathcal O(\widetilde S,S_{-1})=O(g^2/\log g)$ is universal.

Substituting \eqref{eq:obs-explicit-local-dimension-bounds} into
\eqref{eq:bad-only-obstruction-budget} gives
\begin{equation}\label{eq:obs-explicit-summed-obstruction-bound}
 \begin{aligned}
 \dim_{\mathbb F_2}\mathcal O(\widetilde S,S_{-1})
 &\le(324g+324)t+\frac{3g+1}{2}
                    +(2g+2)t+(2g+3)\\
 &=(326g+326)t+\frac{7g+7}{2}.
 \end{aligned}
\end{equation}
It remains to give a numerical bound for $t$.  Write
$\vartheta(x)=\sum_{p\le x}\log p$ and
$\pi(x)=|\{p:p\text{ prime},\ p\le x\}|$.  Every prime $n<p\le2n$ divides
$\binom{2n}{n}$, so
$\vartheta(2n)-\vartheta(n)\le2n\log2$.
For $k\ge1$, summing the inequalities with
$n=2^j$, $0\le j\le k-1$, gives
\begin{equation}\label{eq:obs-mechanical-chebyshev-dyadic-sum}
 \vartheta(2^k)
 \le\sum_{j=0}^{k-1}2^{j+1}\log2
 =2(2^k-1)\log2.
\end{equation}
For $x\ge2$, choose the integer $k\ge1$ with
$2^{k-1}<x\le2^k$. Then
$\vartheta(x)\le\vartheta(2^k)\le4(\log2)x$.
There are at most $\sqrt x$ primes at most $\sqrt x$, and
$\log p>\tfrac12\log x$ for every prime $\sqrt x<p\le x$.
Consequently
\begin{equation}\label{eq:obs-explicit-prime-count-bound}
 \pi(x)\le\sqrt x+\frac{2\vartheta(x)}{\log x}
           \le\sqrt x+\frac{8(\log2)x}{\log x}.
\end{equation}
For $g\ge15$, one has $2g+1\le(31/15)g$ and $\log g\le\sqrt g$.
Substituting $x=2g+1$ into \eqref{eq:obs-explicit-prime-count-bound}
therefore gives
\begin{equation}\label{eq:obs-explicit-omitted-prime-count}
 t\le\pi(2g+1)
 \le\left(\sqrt{31/15}+\frac{248}{15}\log2\right)
                   \frac{g}{\log g}
 <\frac{14g}{\log g}.
\end{equation}
Also $326g+326<350g$ and $(7g+7)/2\le4g$.  By
\eqref{eq:obs-explicit-omitted-prime-count}, equation \eqref{eq:obs-explicit-summed-obstruction-bound} gives
\begin{equation}\label{eq:obs-mechanical-final-numerical-obstruction-bound}
 \dim_{\mathbb F_2}\mathcal O(\widetilde S,S_{-1})
 <\frac{4900g^2}{\log g}+4g
 \le\frac{4904g^2}{\log g}
 <\frac{5000g^2}{\log g},
\end{equation}
as desired.

\label{prop:constructed-tower}
Let $m\ge32768$, put $g=2^m-1$, and let $S_0\to S_{-1}$ and
$s_0:\operatorname{Spec}\mathbb Z\to S_0$ be the surfaces and section constructed in
Propositions~\ref{prop:start-integral-galois} and~\ref{prop:start-integral-section}.
There is a tower
\begin{equation}\label{eq:final-explicit-surface-tower}
 \cdots\longrightarrow S_{n+1}\longrightarrow S_n
       \longrightarrow\cdots\longrightarrow S_0
\end{equation}
with the following properties.
\begin{enumerate}[label=(\roman*)]
\item Every $S_n$ is an integral regular projective flat arithmetic
surface with smooth geometrically integral generic fibre.
\item The map $S_n\to S_0$ is a connected finite \'etale Galois
cover of degree $2^n$.  Each transition $S_{n+1}\to S_n$ has degree
two.
\item The composite $S_n\to S_{-1}$ is Galois. Put
$G_n=\operatorname{Gal}(S_n/S_{-1})$. Then
\begin{equation}\label{eq:final-explicit-group-invariants}
 G_0\simeq\mathbb F_2^g,\qquad |G_n|=2^{g+n},\qquad d(G_n)=g.
\end{equation}
For every $n\ge0$, restriction gives a nonsplit central extension
\begin{equation}\label{eq:final-explicit-central-extension}
 1\longrightarrow\mathbb F_2\longrightarrow G_{n+1}
       \longrightarrow G_n\longrightarrow1.
\end{equation}
\item The section $s_0$ splits completely at every level:
\begin{equation}\label{eq:final-explicit-section-splitting}
 S_n\times_{S_0,s_0}\operatorname{Spec}\mathbb Z
       \simeq\coprod_{j=1}^{2^n}\operatorname{Spec}\mathbb Z.
\end{equation}
\end{enumerate}
